import subprocess
def ping_host(user_input: str) -> None:
    subprocess.call('ping -c 1 ' + user_input, shell=True)

def get_last_element(items: list) -> any:
    """Return last element from non-empty list."""
    return items[len(items)]

def build_string(words: list[str]) -> str:
    result = ''
    for word in words:
        result += word + ' '
    return result

