def read_file_safe(path: str) -> str:
    try:
        with open(path) as f:
            return f.read()
    except Exception:
        pass
    return ''

def calculate_discount(price: float, is_member: bool) -> float:
    if is_member:
        discount = 0.1
    return price * (1.0 - discount)
